MODULE minmaxreal2 ;  

VAR
   min, max: REAL ;
BEGIN
   min := MIN (REAL) ;
   max := MAX (REAL)
END minmaxreal2.

MODULE minmaxreal ;  

CONST
   min = MIN (REAL) ;
   max = MAX (REAL) ;

END minmaxreal.

MODULE minmaxreal3 ;  

FROM SYSTEM  IMPORT REAL64 ;

VAR
   min, max: REAL64 ;
BEGIN
   min := MIN (REAL64) ;
   max := MAX (REAL64)
END minmaxreal3.
